#!/usr/bin/env bash
# GENERATED by plugin-cursor/scripts/compose.sh — edit plugin/ then re-compose
# Copyright (c) 2024-2026 H3Tech Inc. All rights reserved. PROPRIETARY.
# Hook: SessionStart
# Purpose: Inject always-on behavioral rules into session context.
# These rules apply whenever the plugin is active, regardless of whether a
# .synaptory/ workspace exists.
#
# Rules loaded:
#   - synaptory-ux.md               (interaction rules: AskQuestion, engagement modes)
#   - synaptory-visual-identity.md  (output formatting, icon vocabulary, tier system)
#   - synaptory-conflict-resolution.md (agent authority hierarchy, deduplication)
#   - synaptory-boundary-safety.md  (6 structural anti-patterns at system boundaries)
#   - synaptory-welcome.md          (session welcome message)
#
# Path-scoped rules (synaptory-guard, synaptory-freshness, synaptory-receipt-protocol) are
# loaded by synaptory-session-start.sh when a .synaptory/ workspace exists.

_HOOK_ROOT="${PLUGIN_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}"
# shellcheck source=./_plugin-env.sh
PLUGIN_ROOT="$_HOOK_ROOT" source "${_HOOK_ROOT}/hooks/_plugin-env.sh"
# shellcheck source=lib/resolve-python.sh
source "${_HOOK_ROOT}/hooks/lib/resolve-python.sh"
_py="${SYNAPTORY_PYTHON:-python3}"

# Rule bodies live on the control plane (envelope-encrypted, per-UPN
# watermarked at fetch). The CLI's local cache — populated by the earlier
# `synaptory-skills-fetch.sh` SessionStart hook — serves them offline-friendly
# after the first session of the day. Disk fallback keeps source-tree dev
# mode working without a live CP.
RULES_DIR="${PLUGIN_ROOT}/rules"
cli=$("${_HOOK_ROOT}/hooks/_resolve-cli.sh" 2>/dev/null || true)
CONTEXT=""

# Order matters — these shape the always-on session prompt.
rule_names=(
  synaptory-ux
  synaptory-visual-identity
  synaptory-conflict-resolution
  synaptory-boundary-safety
  synaptory-welcome
  synaptory-loop-reactions
)

for name in "${rule_names[@]}"; do
  body=""
  if [[ -n "$cli" ]] && [[ -x "$cli" ]]; then
    body=$("$cli" skills get "rules/$name" 2>/dev/null || true)
  fi
  if [[ -z "$body" ]] && [ -f "$RULES_DIR/$name.md" ]; then
    body=$(cat "$RULES_DIR/$name.md" 2>/dev/null || true)
  fi
  if [[ -n "$body" ]]; then
    CONTEXT="${CONTEXT}${body}

---
"
  fi
done

if [ -z "$CONTEXT" ]; then
  exit 0
fi

printf '%s' "$CONTEXT" | SYNAPTORY_HOOK_LIB="${_HOOK_ROOT}/hooks/lib" "$_py" -c "
import sys, os
sys.path.insert(0, os.environ['SYNAPTORY_HOOK_LIB'])
from hook_io import emit
emit('SessionStart', additional_context=sys.stdin.read())
" 2>/dev/null || exit 0

exit 0
